mapper.select:
SELECT /*检索项目*/ T2.TYPE_6 assetType, T1.FINPROD_MARKET_ID assetId, T1.FINPROD_ABBR assetName, T1.ISSUE_AMT amount, T1.FINPROD_ID, TO_CHAR(T3.TRADE_DATE, 'yyyy-MM-dd') tradeDate, TO_CHAR(T1.VDATE, 'yyyy-MM-dd') vDate, TO_CHAR(T1.MDATE, 'yyyy-MM-dd') mDate, t1.CCY, T4.PAY_CYCLE FROM /*检索表*/ FIN_PRODUCT T1/*标的类金融产品*/ LEFT JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID/*金融产品分类*/ LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN FIN_CASH_PAY_RULE T4 ON T1.FINPROD_ID = T4.FINPROD_ID /*检索条件*/
NOT EXISTS (SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL TFT WHERE TFT.FINPROD_ID = T3.FINPROD_ID AND TFT.TRADE_DATE < T3.TRADE_DATE)
AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F18}
/*and 金融产品分类.分类6 in (画面.项目类型)*/ #{item}
and T1.FINPROD_MARKET_ID = #{assetId}/*标的类金融产品.金融产品代码 in (画面.资产代码)*/
order by T1.MDATE desc/*排列顺序 到期日 降序*/
